void addNum(int x) {
    if (lower.empty() || x <= lower.top())
        lower.push(x);
    else
        upper.push(x);

    // Rebalance
    if (lower.size() > upper.size() + 1) {
        upper.push(lower.top());
        lower.pop();
    } else if (upper.size() > lower.size()) {
        lower.push(upper.top());
        upper.pop();
    }
}

double getMedian() {
    if (lower.size() == upper.size())
        return (lower.top() + upper.top()) / 2.0;
    return lower.top();
}

